// Brain store: what Josh sends the EA (captures, journal lines, chat) and what the EA sends
// back (replies, insights). SETUP: paste the data table id below.
const TABLE_ID = 'REPLACE_WITH_BRAIN_TABLE_ID';
const first = $input.first().json;
const body = first.body || first;
const request_id = (typeof body.request_id === 'string' && body.request_id.length <= 100) ? body.request_id : undefined;
const fail = (code, message, status_code = 400) => [{ json: { valid: false, status_code, error: { code, message }, request_id } }];
const isIso = (v) => typeof v === 'string' && v.trim() !== '' && !isNaN(new Date(v).getTime());
if (TABLE_ID.startsWith('REPLACE')) return fail('SETUP_ERROR', 'brain data table id is not set in Validate Input', 500);
const base = 'http://localhost:5678/api/v1/data-tables/' + TABLE_ID + '/rows';
const op = body.op;
if (!['put', 'list', 'get', 'update'].includes(op)) return fail('VALIDATION_ERROR', 'op must be put, list, get or update');
const KINDS = { josh: ['capture', 'journal', 'chat'], ea: ['reply', 'insight', 'chat'] };
const idOk = (id) => typeof id === 'string' && /^[A-Za-z0-9:_-]{1,100}$/.test(id);
const eq = (col, value) => ({ type: 'and', filters: [{ columnName: col, condition: 'eq', value }] });
const rowsUrl = (filter, limit) => base + '?limit=' + limit + '&sortBy=' + encodeURIComponent('created_at:desc') + (filter ? '&filter=' + encodeURIComponent(JSON.stringify(filter)) : '');
const by = body.by === 'ea' ? 'ea' : 'josh';
const now = new Date().toISOString();

if (op === 'put') {
  const it = body.item;
  if (it == null || typeof it !== 'object' || Array.isArray(it)) return fail('VALIDATION_ERROR', 'item must be an object');
  if (!KINDS[by].includes(it.kind)) return fail('VALIDATION_ERROR', by + ' may put kind ' + KINDS[by].join(' | '));
  if (typeof it.text !== 'string' || it.text.trim() === '' || it.text.length > 20000) return fail('VALIDATION_ERROR', 'item.text must be 1-20000 characters');
  if (it.id != null && !idOk(it.id)) return fail('VALIDATION_ERROR', 'item.id is not a valid id');
  if (it.offlineId != null && !/^[A-Za-z0-9-]{8,100}$/.test(String(it.offlineId))) return fail('VALIDATION_ERROR', 'item.offlineId is not a valid id');
  const data = it.data == null ? {} : it.data;
  if (typeof data !== 'object' || Array.isArray(data) || JSON.stringify(data).length > 100000) return fail('VALIDATION_ERROR', 'item.data must be an object under 100 KB');
  const offlineId = it.offlineId ? String(it.offlineId) : '';
  const itemId = it.id || (offlineId ? 'b-' + offlineId : 'b-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10));
  const row = { item_id: itemId, kind: it.kind, text: it.text, source: typeof it.source === 'string' ? it.source.slice(0, 40) : (by === 'ea' ? 'ea' : 'typed'),
    by, offline_id: offlineId, state: it.kind === 'reply' || it.kind === 'insight' ? 'open' : 'new', data_json: JSON.stringify(data), created_at: now, updated_at: now };
  // read first: a repeated offlineId returns the first item (CONTRACT.md §1.12)
  return [{ json: { valid: true, op, request_id, row, insertUrl: base, req: { url: rowsUrl(eq('offline_id', offlineId || '__none__'), 1) } } }];
}
if (op === 'list') {
  const want = Array.isArray(body.kinds) && body.kinds.length ? body.kinds.filter((k) => typeof k === 'string') : null;
  const states = Array.isArray(body.states) && body.states.length ? body.states.filter((k) => typeof k === 'string') : null;
  const limit = Math.max(1, Math.min(100, parseInt(body.limit ?? 50, 10) || 50));
  return [{ json: { valid: true, op, request_id, want, states, limit, req: { url: rowsUrl(null, 250) } } }];
}
if (!idOk(body.id)) return fail('VALIDATION_ERROR', 'id is required');
if (op === 'get') return [{ json: { valid: true, op, request_id, id: body.id, req: { url: rowsUrl(eq('item_id', body.id), 1) } } }];
// update: state and/or merge into data (routing from the EA; answers, dismissals from the app)
const patch = body.patch;
if (patch == null || typeof patch !== 'object' || Array.isArray(patch)) return fail('VALIDATION_ERROR', 'patch must be an object');
if (patch.state != null && !['new', 'filed', 'open', 'answered', 'dismissed'].includes(patch.state)) return fail('VALIDATION_ERROR', 'state must be new, filed, open, answered or dismissed');
if (patch.data != null && (typeof patch.data !== 'object' || Array.isArray(patch.data))) return fail('VALIDATION_ERROR', 'patch.data must be an object');
if (patch.state == null && patch.data == null) return fail('VALIDATION_ERROR', 'nothing to update');
return [{ json: { valid: true, op, request_id, id: body.id, by, patch, updateUrl: base + '/update', req: { url: rowsUrl(eq('item_id', body.id), 1) } } }];

const v = $('Validate Input').first().json;
const r = $input.first().json || {};
const err = (code, message, status_code) => [{ json: { ok: false, write: false, status_code, request_id: v.request_id, error: { code, message } } }];
if (!(r.statusCode >= 200 && r.statusCode < 300)) return err('UPSTREAM_ERROR', 'data table answered ' + r.statusCode + ': ' + JSON.stringify(r.body || '').slice(0, 300), 502);
const rows = (r.body && Array.isArray(r.body.data)) ? r.body.data : [];
const parse = (s) => { if (!s) return {}; try { return JSON.parse(s); } catch (e) { return {}; } };
const toItem = (row) => ({ id: row.item_id, kind: row.kind, text: row.text, source: row.source, by: row.by, state: row.state,
  offlineId: row.offline_id || null, data: parse(row.data_json), createdAt: row.created_at, updatedAt: row.updated_at });
const ok = (data, extra) => [{ json: Object.assign({ ok: true, write: false, response: { ok: true, request_id: v.request_id, data } }, extra || {}) }];

if (v.op === 'put') {
  if (rows.length && v.row.offline_id) return [{ json: { ok: true, write: false, response: { ok: true, duplicate: true, request_id: v.request_id, data: { item: toItem(rows[0]) } } } }];
  return [{ json: { ok: true, write: true, insert: true, insertUrl: v.insertUrl, row: v.row, response: { ok: true, request_id: v.request_id, data: { item: toItem(v.row) } } } }];
}
if (v.op === 'list') {
  let items = rows.map(toItem);
  if (v.want) items = items.filter((i) => v.want.includes(i.kind));
  if (v.states) items = items.filter((i) => v.states.includes(i.state));
  return ok({ items: items.slice(0, v.limit), truncated: rows.length >= 250 });
}
const row = rows[0];
if (!row) return err('NOT_FOUND', 'item not found', 404);
if (v.op === 'get') return ok({ item: toItem(row) });
// update
const cur = toItem(row);
const nowIso = new Date().toISOString();
const data = Object.assign({}, cur.data, v.patch.data || {});
const next = Object.assign({}, cur, { state: v.patch.state || cur.state, data, updatedAt: nowIso });
return [{ json: { ok: true, write: true, insert: false, updateUrl: v.updateUrl,
  updateBody: { filter: { type: 'and', filters: [{ columnName: 'item_id', condition: 'eq', value: row.item_id }] }, data: { state: next.state, data_json: JSON.stringify(data), updated_at: nowIso }, returnData: false },
  response: { ok: true, request_id: v.request_id, data: { item: next } } } }];

// The write only counts if the data table said so.
const d = $('Decide').first().json;
const r = $input.first().json || {};
if (r.statusCode >= 200 && r.statusCode < 300) return [{ json: { ok: true, response: d.response } }];
return [{ json: { ok: false, status_code: 502, request_id: d.response && d.response.request_id, error: { code: 'UPSTREAM_ERROR', message: 'data table write answered ' + r.statusCode + ': ' + JSON.stringify(r.body || '').slice(0, 300) } } }];
